/**
 * Image credits for every fighter face, generated by the face pipeline into credits.json.
 * Each entry names the source file, author, licence and the edits made, and carries the face's average skin tone.
 * The credits screen lists them and the head model uses the tone so the photo blends into the rest of the head.
 */
import { UnknownEntityError } from '../core/errors';
import data from './credits.json';
import { fighterById } from './roster';

/** Hue range (degrees) and saturation range that plausibly describe skin, marble or sepia; outside it the photo's lighting is off. */
const SKIN_HUE_MAX = 50;
const SKIN_HUE_WRAP_MIN = 340;
const SKIN_SATURATION_MAX = 0.75;
const HEX_RADIX = 16;
const CHANNEL_MAX = 255;

export interface FaceCredit {
  id: string;
  file: string;
  sourceUrl: string;
  author: string;
  license: string;
  licenseUrl: string;
  changes: string;
  /** CSS hex colour such as "#c89a80". */
  tone: string;
}

export const FACE_CREDITS: readonly FaceCredit[] = data.credits;

const BY_ID = new Map(FACE_CREDITS.map((c) => [c.id, c]));

export function creditFor(fighterId: string): FaceCredit {
  const credit = BY_ID.get(fighterId);
  if (!credit) throw new UnknownEntityError(`No face credit for ${fighterId}`);
  return credit;
}

/** Hue in degrees and HSL saturation of a 0xRRGGBB colour. */
export function hueSaturation(color: number): { hue: number; saturation: number } {
  const r = ((color >> 16) & CHANNEL_MAX) / CHANNEL_MAX;
  const g = ((color >> 8) & CHANNEL_MAX) / CHANNEL_MAX;
  const b = (color & CHANNEL_MAX) / CHANNEL_MAX;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;
  const light = (max + min) / 2;
  const saturation = delta === 0 ? 0 : delta / (1 - Math.abs(2 * light - 1));
  let hue = 0;
  if (delta > 0 && max === r) hue = 60 * (((g - b) / delta + 6) % 6);
  else if (delta > 0 && max === g) hue = 60 * ((b - r) / delta + 2);
  else if (delta > 0) hue = 60 * ((r - g) / delta + 4);
  return { hue, saturation };
}

export function isPlausibleSkin(color: number): boolean {
  const { hue, saturation } = hueSaturation(color);
  const warm = hue <= SKIN_HUE_MAX || hue >= SKIN_HUE_WRAP_MIN;
  return saturation <= SKIN_SATURATION_MAX && (warm || saturation < 0.08);
}

/** Head and hand colour: the photo's measured tone, or the roster's skin colour when stage lighting tinted the photo. */
export function toneOf(fighterId: string): number {
  const measured = Number.parseInt(creditFor(fighterId).tone.slice(1), HEX_RADIX);
  return isPlausibleSkin(measured) ? measured : fighterById(fighterId).look.skinColor;
}
